$ErrorActionPreference='Continue'
$root='C:\Users\pc\SmartLedger-Build-Clean-20261010'; $out=Join-Path $root 'runtime_qa_screenshots'; Add-Type -AssemblyName System.Drawing; Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName UIAutomationClient; Add-Type -AssemblyName UIAutomationTypes
Add-Type @'
using System; using System.Runtime.InteropServices; public class QAMouse { [DllImport("user32.dll")] public static extern bool SetCursorPos(int X,int Y); [DllImport("user32.dll")] public static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra); public const uint LEFTDOWN=0x02; public const uint LEFTUP=0x04; }
'@
function SaveShot([string]$name){Start-Sleep -Milliseconds 1000;$b=[System.Windows.Forms.Screen]::PrimaryScreen.Bounds;$bmp=New-Object System.Drawing.Bitmap($b.Width,$b.Height);$g=[System.Drawing.Graphics]::FromImage($bmp);$g.CopyFromScreen($b.Left,$b.Top,0,0,$b.Size);$p=Join-Path $out $name;$bmp.Save($p,[System.Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bmp.Dispose();$log.Add('- '+$name+' captured at '+$b.Width+'x'+$b.Height)}
function ClickAt([int]$x,[int]$y){[void][QAMouse]::SetCursorPos($x,$y);Start-Sleep -Milliseconds 150;[QAMouse]::mouse_event([QAMouse]::LEFTDOWN,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 80;[QAMouse]::mouse_event([QAMouse]::LEFTUP,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 1800}
$log=[System.Collections.Generic.List[string]]::new();$log.Add('## Navigation captures '+(Get-Date -Format s));
# Screen positions map to the visible right-side navigation buttons in the 1920x1080 live session.
$routes=@(@{name='Accounts & Ledgers';y=186;file='03-accounts.png'},@{name='Inventory';y=240;file='04-inventory.png'},@{name='POS & Sales';y=294;file='05-sales-pos.png'},@{name='Purchases';y=348;file='06-purchases.png'},@{name='Operating Expenses';y=402;file='07-expenses.png'},@{name='Reports';y=474;file='08-reports.png'},@{name='System Settings';y=761;file='09-settings.png'},@{name='About & Identity';y=707;file='10-about.png'})
foreach($r in $routes){ClickAt 1800 $r.y;SaveShot $r.file;$rootEl=[System.Windows.Automation.AutomationElement]::RootElement;$children=$rootEl.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$app=$null;foreach($w in $children){try{if($w.Current.Name -match 'SmartLedger'){$app=$w;break}}catch{}};if($app){$log.Add('### '+$r.name);$log.Add('Window: '+$app.Current.Name);try{$els=$app.FindAll([System.Windows.Automation.TreeScope]::Descendants,(New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::IsControlElementProperty,$true)));$i=0;foreach($e in $els){if($i -ge 75){break};try{$n=$e.Current.Name;$t=$e.Current.ControlType.ProgrammaticName;$rc=$e.Current.BoundingRectangle;if($n -or $t -match 'Button|Edit|DataGrid|ComboBox|TabItem|ListItem|Window'){$log.Add(('- [{0}] {1} | enabled={2} | rect={3},{4},{5},{6}' -f $t,$n,$e.Current.IsEnabled,[math]::Round($rc.X),[math]::Round($rc.Y),[math]::Round($rc.Width),[math]::Round($rc.Height)));$i++}}catch{}}}catch{$log.Add('UIA read error: '+$_.Exception.Message)}}else{$log.Add('WARN: no titled SmartLedger root found after click.')};$log.Add('')}
$log | Add-Content -Encoding UTF8 (Join-Path $root 'runtime-qa-initial-observations.txt');Write-Output ('NAVIGATION_ROUTES_CAPTURED='+$routes.Count);Write-Output ('SCREENSHOT_DIR='+$out)
